{"content": "import { NextRequest, NextResponse } from "next/server";
import { buildAuthorizationRequest } from "@/lib/oidc";
import { isValidLang, defaultLanguage } from "@/lib/language";

export const dynamic = "force-dynamic";

export const OIDC_TXN_COOKIE_NAME = "oidc_txn";
const TXN_MAX_AGE_SECONDS = 5 * 60;

// Only allow same-origin relative paths as a redirect target to avoid an open redirect
// (the query parameter is attacker-influenceable via a crafted sign-in link).
function sanitizeReturnTo(value: string | null, fallback: string): string {
  if (!value) return fallback;
  if (!value.startsWith("/") || value.startsWith("//") || value.includes("://")) {
    return fallback;
  }
  return value;
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const rawLang = searchParams.get("lang") ?? "";
  const lang = isValidLang(rawLang) ? rawLang : defaultLanguage;
  const returnTo = sanitizeReturnTo(searchParams.get("return_to"), `/${lang}/console`);

  const { url, txn } = await buildAuthorizationRequest({ lang, returnTo });

  const response = NextResponse.redirect(url);
  response.cookies.set(OIDC_TXN_COOKIE_NAME, JSON.stringify(txn), {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: TXN_MAX_AGE_SECONDS,
  });
  return response;
}
