{"content": "const fs = require("node:fs");

const REMOVED_KEYS = ["de-DE", "pt-PT", "ja", "zh-TW"];
const KEY_PATTERN = new RegExp(
  `^(\\s*)"?(${REMOVED_KEYS.join("|")})"?:\\s(.*)$`
);

function stripRemovedLanguageKeys(filePath) {
  const original = fs.readFileSync(filePath, "utf8");
  const lines = original.split("\n");
  const result = [];
  let i = 0;
  let removedBlocks = 0;

  while (i < lines.length) {
    const line = lines[i];
    const match = line.match(KEY_PATTERN);

    if (!match) {
      result.push(line);
      i += 1;
      continue;
    }

    const [, indent, , rest] = match;
    const trimmedRest = rest.trim();

    if (trimmedRest === "[" || trimmedRest === "{") {
      const closer = trimmedRest === "[" ? `${indent}],` : `${indent}},`;
      let j = i + 1;
      while (j < lines.length && lines[j] !== closer) {
        j += 1;
      }
      if (j >= lines.length) {
        throw new Error(
          `Could not find closer "${closer}" for block starting at line ${i + 1} in ${filePath}`
        );
      }
      // Skip from the opening line (i) through the closer line (j) inclusive.
      i = j + 1;
      removedBlocks += 1;
      continue;
    }

    // Single-line value (e.g. `en: "BaseX",` already excluded — this only matches removed keys).
    i += 1;
    removedBlocks += 1;
  }

  fs.writeFileSync(filePath, result.join("\n"));
  console.log(`${filePath}: removed ${removedBlocks} blocks/lines`);
}

for (const file of process.argv.slice(2)) {
  stripRemovedLanguageKeys(file);
}
